// main.zig — swscale-compatible image scaling / pixel-format conversion.
//
// The arithmetic mirrors FFmpeg's C path (same filters, same intermediate
// precision, same rounding) so results track the reference closely; the hot
// loops are written with @Vector for SIMD.

const std = @import("std");
const k = @import("kernels.zig");

const alloc = std.heap.c_allocator;

pub const YUV420P = 0;
pub const YUV422P = 1;
pub const YUV444P = 2;
pub const NV12 = 3;
pub const NV21 = 4;
pub const RGB24 = 5;
pub const BGR24 = 6;
pub const RGBA = 7;
pub const BGRA = 8;
pub const GRAY8 = 9;

const F_BILINEAR: u32 = 2;
const F_BICUBIC: u32 = 4;
const F_POINT: u32 = 0x10;

fn isRGB(f: i32) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isPlanarYUV(f: i32) bool {
    return f == YUV420P or f == YUV422P or f == YUV444P;
}
fn isNV(f: i32) bool {
    return f == NV12 or f == NV21;
}
fn hSub(f: i32) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn vSub(f: i32) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn ceilShr(a: i32, s: u5) i32 {
    return -((-a) >> s);
}

// ── filter construction (port of initFilter) ───────────────────────────────

pub const Filter = struct {
    pos: []i32,
    coef: []i16,
    size: usize,
    n: usize,
};

fn avLog2(v: u32) i32 {
    return 31 - @as(i32, @clz(v | 1));
}

fn roundedDiv(a: i64, b: i64) i64 {
    return @divTrunc(if (a >= 0) a + (b >> 1) else a - (b >> 1), b);
}

fn initFilter(xInc: i64, srcW: i32, dstW: i32, one: i64, flags: u32, srcPos: i64, dstPos: i64) !Filter {
    const dw: usize = @intCast(dstW);
    const ratio: u32 = @intCast(@divTrunc(srcW, dstW));
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(avLog2(ratio), 8));
    var filterSize: usize = 0;
    var filter: []i64 = undefined;
    const pos = try alloc.alloc(i32, dw + 3);

    if (@abs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        for (0..dw) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (flags & F_POINT != 0) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..dw) |i| {
            const xx: i64 = (xDstInSrc + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i64 = if (flags & F_BICUBIC != 0) 4 else 2;
        var fs: i64 = undefined;
        if (xInc <= 1 << 16) {
            fs = 1 + sizeFactor;
        } else {
            fs = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        fs = @min(fs, srcW - 2);
        fs = @max(fs, 1);
        filterSize = @intCast(fs);
        filter = try alloc.alloc(i64, dw * filterSize);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        for (0..dw) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (fs - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..filterSize) |j| {
                var d: i64 = @as(i64, @intCast(@abs(xx * (1 << 17) - xDstInSrc))) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (flags & F_BICUBIC != 0) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(@as(f64, 0.6) * @as(f64, 1 << 24));
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * filterSize + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }
    defer alloc.free(filter);

    const f2s = filterSize;
    const filter2 = filter;

    // reduce filter size: drop near-zero taps
    var minFilterSize: usize = 0;
    const cutLim: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    var ii: isize = @as(isize, @intCast(dw)) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min = f2s;
        var cutOff: i64 = 0;
        for (0..f2s) |_| {
            cutOff += @intCast(@abs(filter2[i * f2s]));
            if (@as(f64, @floatFromInt(cutOff)) > cutLim) break;
            if (i < dw - 1 and pos[i] >= pos[i + 1]) break;
            var kk: usize = 1;
            while (kk < f2s) : (kk += 1) filter2[i * f2s + kk - 1] = filter2[i * f2s + kk];
            filter2[i * f2s + kk - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var j: usize = f2s - 1;
        while (j > 0) : (j -= 1) {
            cutOff += @intCast(@abs(filter2[i * f2s + j]));
            if (@as(f64, @floatFromInt(cutOff)) > cutLim) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }

    const fsz = minFilterSize;
    const f3 = try alloc.alloc(i64, dw * fsz);
    defer alloc.free(f3);
    for (0..dw) |i| {
        for (0..fsz) |j| {
            f3[i * fsz + j] = if (j >= f2s) 0 else filter2[i * f2s + j];
        }
    }

    // fix borders
    for (0..dw) |i| {
        const f = f3[i * fsz .. (i + 1) * fsz];
        if (pos[i] < 0) {
            for (1..fsz) |j| {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                f[left] += f[j];
                f[j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + @as(i32, @intCast(fsz)) > srcW) {
            const shift: i32 = pos[i] + @min(@as(i32, @intCast(fsz)) - srcW, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (pos[i] + @as(i32, @intCast(j)) >= srcW) {
                    acc += f[ju];
                    f[ju] = 0;
                }
            }
            j = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    f[ju] = 0;
                } else {
                    f[ju] = f[@intCast(j - shift)];
                }
            }
            pos[i] -= shift;
            f[@intCast(srcW - 1 - pos[i])] += acc;
        }
    }

    const out = try alloc.alloc(i16, fsz * (dw + 3));
    @memset(out, 0);
    for (0..dw) |i| {
        var sum: i64 = 0;
        for (0..fsz) |j| sum += f3[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        var err: i64 = 0;
        for (0..fsz) |j| {
            const v = f3[i * fsz + j] + err;
            const intV = roundedDiv(v, sum);
            out[i * fsz + j] = @truncate(intV);
            err = v - intV * sum;
        }
    }
    pos[dw] = pos[dw - 1];
    pos[dw + 1] = pos[dw - 1];
    pos[dw + 2] = pos[dw - 1];
    return .{ .pos = pos, .coef = out, .size = fsz, .n = dw };
}

fn freeFilter(f: *Filter) void {
    alloc.free(f.pos);
    alloc.free(f.coef);
}

// ── context ────────────────────────────────────────────────────────────────

const Kind = enum { generic, yuv2rgb, planar_to_nv, nv_to_planar, bgr24_to_yv12, rgb2rgb, copy };

pub const Ctx = struct {
    sw: usize,
    sh: usize,
    sf: i32,
    dw: usize,
    dh: usize,
    df: i32,
    kind: Kind,

    tabs: k.Tables = undefined,

    // generic
    hLum: Filter = undefined,
    hChr: Filter = undefined,
    vLum: Filter = undefined,
    vChr: Filter = undefined,
    chrSrcW: usize = 0,
    chrSrcH: usize = 0,
    chrDstW: usize = 0,
    chrDstH: usize = 0,
    chrSrcHSub: u5 = 0,
    chrSrcVSub: u5 = 0,
    chrDstHSub: u5 = 0,
    chrDstVSub: u5 = 0,
    fullChr: bool = false,
    needAlpha: bool = false,
    lumRange: u8 = 0, // 0 none, 1 to jpeg, 2 from jpeg

    lumBuf: []i16 = &.{},
    alpBuf: []i16 = &.{},
    chrUBuf: []i16 = &.{},
    chrVBuf: []i16 = &.{},
    tmpA: []i16 = &.{},
    tmpB: []i16 = &.{},
    tmpC: []i16 = &.{},
    tmpU8: []u8 = &.{},
    tmpV8: []u8 = &.{},
    lumNeeded: []bool = &.{},
    chrNeeded: []bool = &.{},
    hLumIdent: bool = false,
    hChrIdent: bool = false,
};

fn genericSetup(c: *Ctx, algo: i32) !void {
    const srcW: i32 = @intCast(c.sw);
    const srcH: i32 = @intCast(c.sh);
    const dstW: i32 = @intCast(c.dw);
    const dstH: i32 = @intCast(c.dh);
    var flags: u32 = switch (algo) {
        0 => F_POINT,
        2 => F_BICUBIC,
        else => F_BILINEAR,
    };
    _ = &flags;

    c.chrSrcHSub = hSub(c.sf);
    c.chrSrcVSub = vSub(c.sf);
    c.chrDstHSub = hSub(c.df);
    c.chrDstVSub = vSub(c.df);

    var full = false;
    if (isRGB(c.df)) {
        if (dstW & 1 != 0) full = true;
        if (c.chrSrcHSub == 0 and c.chrSrcVSub == 0) full = true;
        if (!full) c.chrDstHSub = 1;
    }
    c.fullChr = full;

    if (isRGB(c.sf) and ((dstW >> c.chrDstHSub) <= (srcW >> 1)))
        c.chrSrcHSub = 1;

    c.chrSrcW = @intCast(ceilShr(srcW, c.chrSrcHSub));
    c.chrSrcH = @intCast(ceilShr(srcH, c.chrSrcVSub));
    c.chrDstW = @intCast(ceilShr(dstW, c.chrDstHSub));
    c.chrDstH = @intCast(ceilShr(dstH, c.chrDstVSub));

    const lumXInc: i64 = @divTrunc((@as(i64, srcW) << 16) + (dstW >> 1), dstW);
    const lumYInc: i64 = @divTrunc((@as(i64, srcH) << 16) + (dstH >> 1), dstH);
    const cdw: i64 = @intCast(c.chrDstW);
    const cdh: i64 = @intCast(c.chrDstH);
    const chrXInc: i64 = @divTrunc((@as(i64, @intCast(c.chrSrcW)) << 16) + (cdw >> 1), cdw);
    const chrYInc: i64 = @divTrunc((@as(i64, @intCast(c.chrSrcH)) << 16) + (cdh >> 1), cdh);

    c.hLum = try initFilter(lumXInc, srcW, dstW, 1 << 14, flags, 128, 128);
    c.hChr = try initFilter(chrXInc, @intCast(c.chrSrcW), @intCast(c.chrDstW), 1 << 14, flags, 128, 128);
    c.vLum = try initFilter(lumYInc, srcH, dstH, 1 << 12, flags, 128, 128);
    c.vChr = try initFilter(chrYInc, @intCast(c.chrSrcH), @intCast(c.chrDstH), 1 << 12, flags, 128, 128);

    c.needAlpha = (c.sf == RGBA or c.sf == BGRA) and (c.df == RGBA or c.df == BGRA);

    const srcRange: u8 = if (c.sf == GRAY8) 1 else 0;
    const dstRange: u8 = if (c.df == GRAY8) 1 else 0;
    if (srcRange != dstRange and !isRGB(c.df)) {
        c.lumRange = if (srcRange == 1) 2 else 1;
    }
    c.tabs = k.Tables.init(srcRange == 1, c.df);

    c.hLumIdent = isIdent(&c.hLum);
    c.hChrIdent = isIdent(&c.hChr);

    // buffers
    c.lumBuf = try alloc.alloc(i16, c.sh * c.dw + 64);
    if (c.needAlpha) c.alpBuf = try alloc.alloc(i16, c.sh * c.dw + 64);
    const hasChr = c.df != GRAY8;
    if (hasChr) {
        c.chrUBuf = try alloc.alloc(i16, c.chrSrcH * c.chrDstW + 64);
        c.chrVBuf = try alloc.alloc(i16, c.chrSrcH * c.chrDstW + 64);
        if (c.sf == GRAY8) {
            @memset(c.chrUBuf, 1 << 14);
            @memset(c.chrVBuf, 1 << 14);
        }
    }
    const tw = c.sw + 64;
    c.tmpA = try alloc.alloc(i16, tw);
    c.tmpB = try alloc.alloc(i16, tw);
    c.tmpC = try alloc.alloc(i16, tw);
    c.tmpU8 = try alloc.alloc(u8, tw);
    c.tmpV8 = try alloc.alloc(u8, tw);

    c.lumNeeded = try alloc.alloc(bool, c.sh);
    @memset(c.lumNeeded, false);
    for (0..c.dh) |y| {
        const p: usize = @intCast(c.vLum.pos[y]);
        for (0..c.vLum.size) |j| {
            if (p + j < c.sh) c.lumNeeded[p + j] = true;
        }
    }
    c.chrNeeded = try alloc.alloc(bool, c.chrSrcH);
    @memset(c.chrNeeded, false);
    if (isRGB(c.df)) {
        for (0..c.dh) |y| {
            const cy = y >> c.chrDstVSub;
            const p: usize = @intCast(c.vChr.pos[cy]);
            for (0..c.vChr.size) |j| {
                if (p + j < c.chrSrcH) c.chrNeeded[p + j] = true;
            }
        }
    } else {
        for (0..c.chrDstH) |cy| {
            const p: usize = @intCast(c.vChr.pos[cy]);
            for (0..c.vChr.size) |j| {
                if (p + j < c.chrSrcH) c.chrNeeded[p + j] = true;
            }
        }
    }
}

fn isIdent(f: *const Filter) bool {
    if (f.size != 1) return false;
    for (0..f.n) |i| {
        if (f.pos[i] != @as(i32, @intCast(i)) or f.coef[i] != 1 << 14) return false;
    }
    return true;
}

fn processGeneric(c: *Ctx, src: [4][*]const u8, ss: [4]isize, dst: [4][*]u8, ds: [4]isize) void {
    const sw = c.sw;
    const dw = c.dw;
    // ── horizontal luma ──
    for (0..c.sh) |y| {
        if (!c.lumNeeded[y]) continue;
        const row = src[0] + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const out = c.lumBuf[y * dw .. y * dw + dw];
        if (isRGB(c.sf)) {
            k.rgbToY(c.sf, row, c.tmpA.ptr, sw, &c.tabs);
            if (c.hLumIdent) k.ident16(c.tmpA.ptr, out.ptr, dw) else k.hscale16(c.tmpA.ptr, out.ptr, &c.hLum);
            if (c.needAlpha) {
                k.rgbaToA(c.sf, row, c.tmpB.ptr, sw);
                const aout = c.alpBuf[y * dw .. y * dw + dw];
                if (c.hLumIdent) k.ident16(c.tmpB.ptr, aout.ptr, dw) else k.hscale16(c.tmpB.ptr, aout.ptr, &c.hLum);
            }
        } else {
            if (c.hLumIdent) k.ident8(row, out.ptr, dw) else k.hscale8(row, out.ptr, &c.hLum);
        }
        if (c.lumRange == 1) k.lumToJpeg(out) else if (c.lumRange == 2) k.lumFromJpeg(out);
    }
    // ── horizontal chroma ──
    if (c.df != GRAY8 and c.sf != GRAY8) {
        const cdw = c.chrDstW;
        for (0..c.chrSrcH) |cy| {
            if (!c.chrNeeded[cy]) continue;
            const uo = c.chrUBuf[cy * cdw .. cy * cdw + cdw];
            const vo = c.chrVBuf[cy * cdw .. cy * cdw + cdw];
            if (isRGB(c.sf)) {
                const row = src[0] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ss[0]));
                if (c.chrSrcHSub == 1) {
                    k.rgbToUVHalf(c.sf, row, c.tmpB.ptr, c.tmpC.ptr, c.chrSrcW, &c.tabs);
                } else {
                    k.rgbToUV(c.sf, row, c.tmpB.ptr, c.tmpC.ptr, c.chrSrcW, &c.tabs);
                }
                if (c.hChrIdent) {
                    k.ident16(c.tmpB.ptr, uo.ptr, cdw);
                    k.ident16(c.tmpC.ptr, vo.ptr, cdw);
                } else {
                    k.hscale16(c.tmpB.ptr, uo.ptr, &c.hChr);
                    k.hscale16(c.tmpC.ptr, vo.ptr, &c.hChr);
                }
            } else {
                var urow: [*]const u8 = undefined;
                var vrow: [*]const u8 = undefined;
                if (isNV(c.sf)) {
                    const row = src[1] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ss[1]));
                    for (0..c.chrSrcW) |i| {
                        c.tmpU8[i] = row[2 * i];
                        c.tmpV8[i] = row[2 * i + 1];
                    }
                    if (c.sf == NV12) {
                        urow = c.tmpU8.ptr;
                        vrow = c.tmpV8.ptr;
                    } else {
                        urow = c.tmpV8.ptr;
                        vrow = c.tmpU8.ptr;
                    }
                } else {
                    urow = src[1] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ss[1]));
                    vrow = src[2] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ss[2]));
                }
                if (c.hChrIdent) {
                    k.ident8(urow, uo.ptr, cdw);
                    k.ident8(vrow, vo.ptr, cdw);
                } else {
                    k.hscale8(urow, uo.ptr, &c.hChr);
                    k.hscale8(vrow, vo.ptr, &c.hChr);
                }
            }
        }
    }

    // ── vertical + output ──
    var lrows: [256][*]const i16 = undefined;
    var arows: [256][*]const i16 = undefined;
    var urows: [256][*]const i16 = undefined;
    var vrows: [256][*]const i16 = undefined;
    const lsz = c.vLum.size;
    const csz = c.vChr.size;
    const cdw = c.chrDstW;
    for (0..c.dh) |y| {
        const lp: usize = @intCast(c.vLum.pos[y]);
        for (0..lsz) |j| {
            lrows[j] = c.lumBuf.ptr + (lp + j) * dw;
            if (c.needAlpha) arows[j] = c.alpBuf.ptr + (lp + j) * dw;
        }
        const lf = c.vLum.coef[y * lsz .. y * lsz + lsz];
        const drow = dst[0] + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        if (!isRGB(c.df)) {
            k.planeOut(lf, lrows[0..lsz], drow, dw);
            if (c.df == GRAY8) continue;
            const mask = (@as(usize, 1) << c.chrDstVSub) - 1;
            if (y & mask != 0) continue;
            const cy = y >> c.chrDstVSub;
            const cp: usize = @intCast(c.vChr.pos[cy]);
            for (0..csz) |j| {
                urows[j] = c.chrUBuf.ptr + (cp + j) * cdw;
                vrows[j] = c.chrVBuf.ptr + (cp + j) * cdw;
            }
            const cf = c.vChr.coef[cy * csz .. cy * csz + csz];
            if (isNV(c.df)) {
                const d1 = dst[1] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[1]));
                if (c.df == NV12)
                    k.nvOut(cf, urows[0..csz], vrows[0..csz], d1, cdw)
                else
                    k.nvOut(cf, vrows[0..csz], urows[0..csz], d1, cdw);
            } else {
                const d1 = dst[1] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[1]));
                const d2 = dst[2] + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[2]));
                k.planeOut(cf, urows[0..csz], d1, cdw);
                k.planeOut(cf, vrows[0..csz], d2, cdw);
            }
        } else {
            const cy = y >> c.chrDstVSub;
            const cp: usize = @intCast(c.vChr.pos[cy]);
            for (0..csz) |j| {
                urows[j] = c.chrUBuf.ptr + (cp + j) * cdw;
                vrows[j] = c.chrVBuf.ptr + (cp + j) * cdw;
            }
            const cf = c.vChr.coef[cy * csz .. cy * csz + csz];
            const pk = k.Packed{
                .lf = lf,
                .cf = cf,
                .l = lrows[0..lsz],
                .u = urows[0..csz],
                .v = vrows[0..csz],
                .a = if (c.needAlpha) arows[0..lsz] else null,
                .dst = drow,
                .w = dw,
            };
            k.packedOut(c.df, c.fullChr, &pk, &c.tabs);
        }
    }
}

// ── unscaled special converters ────────────────────────────────────────────

fn rowp(p: [*]const u8, y: usize, s: isize) [*]const u8 {
    return p + @as(usize, @intCast(@as(isize, @intCast(y)) * s));
}
fn rowpm(p: [*]u8, y: usize, s: isize) [*]u8 {
    return p + @as(usize, @intCast(@as(isize, @intCast(y)) * s));
}

fn processUnscaled(c: *Ctx, src: [4][*]const u8, ss: [4]isize, dst: [4][*]u8, ds: [4]isize) void {
    const w = c.sw;
    const h = c.sh;
    switch (c.kind) {
        .yuv2rgb => {
            const v420 = c.sf == YUV420P;
            for (0..h) |y| {
                const cy = if (v420) y >> 1 else y;
                k.yuv2rgbRow(c.df, rowp(src[0], y, ss[0]), rowp(src[1], cy, ss[1]), rowp(src[2], cy, ss[2]), rowpm(dst[0], y, ds[0]), w, &c.tabs);
            }
        },
        .planar_to_nv => {
            for (0..h) |y| @memcpy(rowpm(dst[0], y, ds[0])[0..w], rowp(src[0], y, ss[0])[0..w]);
            const cw = (w + 1) / 2;
            const ch = (h + 1) / 2;
            const a: usize = if (c.df == NV12) 1 else 2;
            const b: usize = 3 - a;
            for (0..ch) |y| k.interleave(rowp(src[a], y, ss[a]), rowp(src[b], y, ss[b]), rowpm(dst[1], y, ds[1]), cw);
        },
        .nv_to_planar => {
            for (0..h) |y| @memcpy(rowpm(dst[0], y, ds[0])[0..w], rowp(src[0], y, ss[0])[0..w]);
            const cw = (w + 1) / 2;
            const ch = (h + 1) / 2;
            const a: usize = if (c.sf == NV12) 1 else 2;
            const b: usize = 3 - a;
            for (0..ch) |y| k.deinterleave(rowp(src[1], y, ss[1]), rowpm(dst[a], y, ds[a]), rowpm(dst[b], y, ds[b]), cw);
        },
        .bgr24_to_yv12 => {
            var y: usize = 0;
            while (y + 1 < h) : (y += 2) {
                k.bgr24ToYv12Rows(rowp(src[0], y, ss[0]), rowp(src[0], y + 1, ss[0]), rowpm(dst[0], y, ds[0]), rowpm(dst[0], y + 1, ds[0]), rowpm(dst[1], y >> 1, ds[1]), rowpm(dst[2], y >> 1, ds[2]), w, &c.tabs);
            }
        },
        .rgb2rgb => {
            for (0..h) |y| k.rgb2rgbRow(c.sf, c.df, rowp(src[0], y, ss[0]), rowpm(dst[0], y, ds[0]), w);
        },
        .copy => {
            const np: usize = if (isPlanarYUV(c.sf)) 3 else if (isNV(c.sf)) 2 else 1;
            for (0..np) |p| {
                var rb: usize = w;
                var rows: usize = h;
                if (p > 0) {
                    rb = @intCast(ceilShr(@intCast(w), hSub(c.sf)));
                    if (isNV(c.sf)) rb *= 2;
                    rows = @intCast(ceilShr(@intCast(h), vSub(c.sf)));
                } else if (c.sf == RGB24 or c.sf == BGR24) {
                    rb = w * 3;
                } else if (c.sf == RGBA or c.sf == BGRA) {
                    rb = w * 4;
                }
                for (0..rows) |y| @memcpy(rowpm(dst[p], y, ds[p])[0..rb], rowp(src[p], y, ss[p])[0..rb]);
            }
        },
        .generic => unreachable,
    }
}

// ── exported functions ─────────────────────────────────────────────────────

fn createImpl(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) !*Ctx {
    if (src_fmt < 0 or src_fmt > 9 or dst_fmt < 0 or dst_fmt > 9) return error.Bad;
    if (src_w < 1 or src_h < 1 or dst_w < 1 or dst_h < 1) return error.Bad;
    if (algo < 0 or algo > 2) return error.Bad;
    const c = try alloc.create(Ctx);
    c.* = .{
        .sw = @intCast(src_w),
        .sh = @intCast(src_h),
        .sf = src_fmt,
        .dw = @intCast(dst_w),
        .dh = @intCast(dst_h),
        .df = dst_fmt,
        .kind = .generic,
    };
    const sf = src_fmt;
    const df = dst_fmt;
    if (src_w == dst_w and src_h == dst_h) {
        if (sf == YUV420P and isNV(df)) {
            c.kind = .planar_to_nv;
        } else if (isNV(sf) and df == YUV420P) {
            c.kind = .nv_to_planar;
        } else if ((sf == YUV420P or sf == YUV422P) and isRGB(df) and (dst_h & 1) == 0) {
            c.kind = .yuv2rgb;
            c.tabs = k.Tables.init(false, df);
        } else if (sf == BGR24 and df == YUV420P and (dst_w & 1) == 0) {
            c.kind = .bgr24_to_yv12;
            c.tabs = k.Tables.init(false, df);
        } else if (isRGB(sf) and isRGB(df) and sf != df) {
            c.kind = .rgb2rgb;
        } else if (sf == df) {
            c.kind = .copy;
        }
    }
    if (c.kind == .generic) try genericSetup(c, algo);
    return c;
}

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    const c = createImpl(src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo) catch return null;
    return @ptrCast(c);
}

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    var src: [4][*]const u8 = undefined;
    var dst: [4][*]u8 = undefined;
    var ss: [4]isize = undefined;
    var ds: [4]isize = undefined;
    const p0 = src_data[0] orelse return -1;
    const q0 = dst_data[0] orelse return -1;
    for (0..4) |i| {
        src[i] = src_data[i] orelse p0;
        dst[i] = dst_data[i] orelse q0;
        ss[i] = src_stride[i];
        ds[i] = dst_stride[i];
    }
    if (c.kind == .generic) processGeneric(c, src, ss, dst, ds) else processUnscaled(c, src, ss, dst, ds);
    return 0;
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return));
    if (c.kind == .generic) {
        freeFilter(&c.hLum);
        freeFilter(&c.hChr);
        freeFilter(&c.vLum);
        freeFilter(&c.vChr);
        alloc.free(c.lumBuf);
        if (c.alpBuf.len > 0) alloc.free(c.alpBuf);
        if (c.chrUBuf.len > 0) alloc.free(c.chrUBuf);
        if (c.chrVBuf.len > 0) alloc.free(c.chrVBuf);
        alloc.free(c.tmpA);
        alloc.free(c.tmpB);
        alloc.free(c.tmpC);
        alloc.free(c.tmpU8);
        alloc.free(c.tmpV8);
        alloc.free(c.lumNeeded);
        alloc.free(c.chrNeeded);
    }
    alloc.destroy(c);
}

