// kernels.zig — per-row conversion kernels and colour tables.

const std = @import("std");
const main = @import("main.zig");
const Filter = main.Filter;

const RY = 0;
const GY = 1;
const BY = 2;
const RU = 3;
const GU = 4;
const BU = 5;
const RV = 6;
const GV = 7;
const BV = 8;

const YB: i32 = 2048; // base offset of the luma table
const YT: usize = 2048 * 3;

fn clipU8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}

fn roundToInt16(f: i64) i32 {
    const r: i64 = (f + (1 << 15)) >> 16;
    if (r < -0x7FFF) return -32768;
    if (r > 0x7FFF) return 0x7FFF;
    return @intCast(r);
}

fn dbl(x: f64, a: f64) i32 {
    // (int)(x * a / 255 * (1 << 15) + 0.5) evaluated in double, like C
    var v: f64 = x;
    v = v * a;
    v = v / 255.0;
    v = v * 32768.0;
    v = v + 0.5;
    return @intFromFloat(v);
}

pub const Tables = struct {
    rgb2yuv: [9]i32,
    ytab: [YT]u8,
    rV: [1280]i32,
    gU: [1280]i32,
    gV: [1280]i32,
    bU: [1280]i32,
    yCoeff: i32,
    yOffset: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,

    pub fn init(fullRange: bool, dstFmt: i32) Tables {
        _ = dstFmt;
        var t: Tables = undefined;
        // rgb -> yuv coefficients (default BT.601 table override)
        t.rgb2yuv[BY] = dbl(0.114, 219);
        t.rgb2yuv[BV] = -dbl(0.081, 224);
        t.rgb2yuv[BU] = dbl(0.500, 224);
        t.rgb2yuv[GY] = dbl(0.587, 219);
        t.rgb2yuv[GV] = -dbl(0.419, 224);
        t.rgb2yuv[GU] = -dbl(0.331, 224);
        t.rgb2yuv[RY] = dbl(0.299, 219);
        t.rgb2yuv[RV] = dbl(0.500, 224);
        t.rgb2yuv[RU] = -dbl(0.169, 224);

        // yuv -> rgb
        var crv: i64 = 104597;
        var cbu: i64 = 132201;
        var cgu: i64 = -25675;
        var cgv: i64 = -53279;
        var cy: i64 = 1 << 16;
        var oy: i64 = 0;
        if (!fullRange) {
            cy = @divTrunc(cy * 255, 219);
            oy = 16 << 16;
        } else {
            crv = @divTrunc(crv * 224, 255);
            cbu = @divTrunc(cbu * 224, 255);
            cgu = @divTrunc(cgu * 224, 255);
            cgv = @divTrunc(cgv * 224, 255);
        }
        // contrast = saturation = 1<<16, brightness 0
        cy = (cy * 65536) >> 16;
        crv = (crv * 65536 * 65536) >> 32;
        cbu = (cbu * 65536 * 65536) >> 32;
        cgu = (cgu * 65536 * 65536) >> 32;
        cgv = (cgv * 65536 * 65536) >> 32;

        t.yCoeff = roundToInt16(cy * (1 << 13));
        t.yOffset = roundToInt16(oy * (1 << 9));
        t.v2r = roundToInt16(crv * (1 << 13));
        t.v2g = roundToInt16(cgv * (1 << 13));
        t.u2g = roundToInt16(cgu * (1 << 13));
        t.u2b = roundToInt16(cbu * (1 << 13));

        crv = @divTrunc((crv * (1 << 16)) + 0x8000, @max(cy, 1));
        cbu = @divTrunc((cbu * (1 << 16)) + 0x8000, @max(cy, 1));
        cgu = @divTrunc((cgu * (1 << 16)) + 0x8000, @max(cy, 1));
        cgv = @divTrunc((cgv * (1 << 16)) + 0x8000, @max(cy, 1));

        const yb0: i64 = -(384 << 16) - 512 * cy - oy;
        for (0..YT) |idx| {
            const i: i64 = @as(i64, @intCast(idx)) - YB;
            const yb = yb0 + i * cy;
            t.ytab[idx] = clipU8(@intCast(std.math.clamp((yb + 0x8000) >> 16, -1000, 1000)));
        }
        const yoffs: i64 = (if (fullRange) @as(i64, 384) else 326) + 512;
        for (0..1280) |idx| {
            const cv: i64 = std.math.clamp(@as(i64, @intCast(idx)) - 512, 0, 255);
            t.rV[idx] = @intCast(YB + yoffs - (crv >> 9) + ((cv * crv) >> 16));
            t.gU[idx] = @intCast(YB + yoffs - (cgu >> 9) + ((cv * cgu) >> 16));
            t.bU[idx] = @intCast(YB + yoffs - (cbu >> 9) + ((cv * cbu) >> 16));
            t.gV[idx] = @intCast(-(cgv >> 9) + ((cv * cgv) >> 16));
        }
        return t;
    }
};

// ── channel layout helpers ─────────────────────────────────────────────────

fn bpp(f: i32) usize {
    return if (f == main.RGBA or f == main.BGRA) 4 else 3;
}
fn rOff(f: i32) usize {
    return if (f == main.RGB24 or f == main.RGBA) 0 else 2;
}
fn bOff(f: i32) usize {
    return 2 - rOff(f);
}

// ── input converters (to 14-bit int16) ─────────────────────────────────────

pub fn rgbToY(f: i32, src: [*]const u8, dst: [*]i16, w: usize, t: *const Tables) void {
    switch (f) {
        main.RGB24 => rgbToYT(3, 0, src, dst, w, t),
        main.BGR24 => rgbToYT(3, 2, src, dst, w, t),
        main.RGBA => rgbToYT(4, 0, src, dst, w, t),
        else => rgbToYT(4, 2, src, dst, w, t),
    }
}

fn rgbToYT(comptime B: usize, comptime R: usize, src: [*]const u8, dst: [*]i16, w: usize, t: *const Tables) void {
    const ry = t.rgb2yuv[RY];
    const gy = t.rgb2yuv[GY];
    const by = t.rgb2yuv[BY];
    for (0..w) |i| {
        const r: i32 = src[i * B + R];
        const g: i32 = src[i * B + 1];
        const b: i32 = src[i * B + 2 - R];
        dst[i] = @intCast((ry * r + gy * g + by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbaToA(f: i32, src: [*]const u8, dst: [*]i16, w: usize) void {
    _ = f;
    for (0..w) |i| {
        const a: i32 = src[4 * i + 3];
        dst[i] = @intCast((a << 6) | (a >> 2));
    }
}

pub fn rgbToUV(f: i32, src: [*]const u8, du: [*]i16, dv: [*]i16, w: usize, t: *const Tables) void {
    const B = bpp(f);
    const R = rOff(f);
    const Bo = bOff(f);
    const ru = t.rgb2yuv[RU];
    const gu = t.rgb2yuv[GU];
    const bu = t.rgb2yuv[BU];
    const rv = t.rgb2yuv[RV];
    const gv = t.rgb2yuv[GV];
    const bv = t.rgb2yuv[BV];
    for (0..w) |i| {
        const r: i32 = src[i * B + R];
        const g: i32 = src[i * B + 1];
        const b: i32 = src[i * B + Bo];
        du[i] = @intCast((ru * r + gu * g + bu * b + (256 << 14) + (1 << 8)) >> 9);
        dv[i] = @intCast((rv * r + gv * g + bv * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUVHalf(f: i32, src: [*]const u8, du: [*]i16, dv: [*]i16, w: usize, t: *const Tables) void {
    const B = bpp(f);
    const R = rOff(f);
    const Bo = bOff(f);
    const ru = t.rgb2yuv[RU];
    const gu = t.rgb2yuv[GU];
    const bu = t.rgb2yuv[BU];
    const rv = t.rgb2yuv[RV];
    const gv = t.rgb2yuv[GV];
    const bv = t.rgb2yuv[BV];
    for (0..w) |i| {
        const r: i32 = @as(i32, src[2 * i * B + R]) + src[(2 * i + 1) * B + R];
        const g: i32 = @as(i32, src[2 * i * B + 1]) + src[(2 * i + 1) * B + 1];
        const b: i32 = @as(i32, src[2 * i * B + Bo]) + src[(2 * i + 1) * B + Bo];
        du[i] = @intCast((ru * r + gu * g + bu * b + (256 << 15) + (1 << 9)) >> 10);
        dv[i] = @intCast((rv * r + gv * g + bv * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

// ── horizontal scalers ─────────────────────────────────────────────────────

pub fn ident8(src: [*]const u8, dst: [*]i16, w: usize) void {
    for (0..w) |i| dst[i] = @as(i16, src[i]) << 7;
}

pub fn ident16(src: [*]const i16, dst: [*]i16, w: usize) void {
    for (0..w) |i| dst[i] = src[i] *% 2;
}

pub fn hscale8(src: [*]const u8, dst: [*]i16, f: *const Filter) void {
    const fs = f.size;
    for (0..f.n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, src[p + j]) * f.coef[i * fs + j];
        dst[i] = @intCast(@min(val >> 7, 32767));
    }
}

pub fn hscale16(src: [*]const i16, dst: [*]i16, f: *const Filter) void {
    const fs = f.size;
    for (0..f.n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, @as(u16, @bitCast(src[p + j]))) * f.coef[i * fs + j];
        dst[i] = @intCast(@min(val >> 13, 32767));
    }
}

pub fn lumToJpeg(d: []i16) void {
    for (d) |*v| {
        const x: i32 = @min(@as(i32, v.*), 30189);
        v.* = @intCast((x * 19077 - 39057361) >> 14);
    }
}

pub fn lumFromJpeg(d: []i16) void {
    for (d) |*v| {
        const x: i32 = v.*;
        v.* = @truncate((x * 14071 + 33561947) >> 14);
    }
}

// ── vertical scalers / planar output ───────────────────────────────────────

pub fn planeOut(f: []const i16, rows: []const [*]const i16, dst: [*]u8, w: usize) void {
    if (f.len == 1) {
        const s = rows[0];
        for (0..w) |i| dst[i] = clipU8((@as(i32, s[i]) + 64) >> 7);
        return;
    }
    for (0..w) |i| {
        var val: i32 = 64 << 12;
        for (f, 0..) |c, j| val += @as(i32, rows[j][i]) * c;
        dst[i] = clipU8(val >> 19);
    }
}

pub fn nvOut(f: []const i16, ur: []const [*]const i16, vr: []const [*]const i16, dst: [*]u8, w: usize) void {
    for (0..w) |i| {
        var u: i32 = 64 << 12;
        var v: i32 = 64 << 12;
        for (f, 0..) |c, j| {
            u += @as(i32, ur[j][i]) * c;
            v += @as(i32, vr[j][i]) * c;
        }
        dst[2 * i] = clipU8(u >> 19);
        dst[2 * i + 1] = clipU8(v >> 19);
    }
}

// ── packed RGB output ──────────────────────────────────────────────────────

pub const Packed = struct {
    lf: []const i16,
    cf: []const i16,
    l: []const [*]const i16,
    u: []const [*]const i16,
    v: []const [*]const i16,
    a: ?[]const [*]const i16,
    dst: [*]u8,
    w: usize,
};

inline fn put(comptime F: i32, d: [*]u8, i: usize, r: u8, g: u8, b: u8, a: u8) void {
    const B = comptime bpp(F);
    const R = comptime rOff(F);
    d[i * B + R] = r;
    d[i * B + 1] = g;
    d[i * B + 2 - R] = b;
    if (B == 4) d[i * B + 3] = a;
}

inline fn tabIdx(v: i32) usize {
    return @intCast(std.math.clamp(v + 512, 0, 1279));
}

inline fn putHalf(comptime F: i32, d: [*]u8, i: usize, Y1: i32, Y2: i32, U: i32, V: i32, t: *const Tables) void {
    const ui = tabIdx(U);
    const vi = tabIdx(V);
    const r = t.rV[vi];
    const g = t.gU[ui] + t.gV[vi];
    const b = t.bU[ui];
    put(F, d, 2 * i, t.ytab[@intCast(Y1 + r)], t.ytab[@intCast(Y1 + g)], t.ytab[@intCast(Y1 + b)], 255);
    put(F, d, 2 * i + 1, t.ytab[@intCast(Y2 + r)], t.ytab[@intCast(Y2 + g)], t.ytab[@intCast(Y2 + b)], 255);
}

inline fn clip30(x: i32) i32 {
    if (x & ~@as(i32, (1 << 30) - 1) != 0) return (~x >> 31) & ((1 << 30) - 1);
    return x;
}

inline fn putFull(comptime F: i32, d: [*]u8, i: usize, Yin: i32, U: i32, V: i32, A: i32, t: *const Tables) void {
    var Y = Yin - t.yOffset;
    Y = Y *% t.yCoeff;
    Y +%= 1 << 21;
    var R: i32 = Y +% V *% t.v2r;
    var G: i32 = Y +% V *% t.v2g +% U *% t.u2g;
    var B: i32 = Y +% U *% t.u2b;
    if ((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000))) != 0) {
        R = clip30(R);
        G = clip30(G);
        B = clip30(B);
    }
    put(F, d, i, @intCast(R >> 22), @intCast(G >> 22), @intCast(B >> 22), @truncate(@as(u32, @bitCast(A))));
}

fn u16eq(a: i16, b: i16) bool {
    return @as(i32, @as(u16, @bitCast(a))) + @as(i32, @as(u16, @bitCast(b))) == 4096 and @as(u16, @bitCast(b)) <= 4096;
}

pub fn packedOut(f: i32, full: bool, p: *const Packed, t: *const Tables) void {
    switch (f) {
        main.RGB24 => packedOutT(main.RGB24, full, p, t),
        main.BGR24 => packedOutT(main.BGR24, full, p, t),
        main.RGBA => packedOutT(main.RGBA, full, p, t),
        else => packedOutT(main.BGRA, full, p, t),
    }
}

fn packedOutT(comptime F: i32, full: bool, p: *const Packed, t: *const Tables) void {
    const ls = p.lf.len;
    const cs = p.cf.len;
    var mode: u8 = 3; // 1: packed1, 2: packed2, 3: X
    var uvalpha: i32 = 0;
    var yalpha: i32 = 0;
    if (ls == 1 and cs == 1) {
        mode = 1;
    } else if (ls == 1 and cs == 2 and u16eq(p.cf[0], p.cf[1])) {
        mode = 1;
        uvalpha = @as(u16, @bitCast(p.cf[1]));
    } else if (ls == 2 and cs == 2 and u16eq(p.lf[0], p.lf[1]) and u16eq(p.cf[0], p.cf[1])) {
        mode = 2;
        yalpha = @as(u16, @bitCast(p.lf[1]));
        uvalpha = @as(u16, @bitCast(p.cf[1]));
    }
    const d = p.dst;
    const w = p.w;
    if (full) {
        const hasA = p.a != null;
        switch (mode) {
            1 => {
                const b0 = p.l[0];
                const u0 = p.u[0];
                const v0 = p.v[0];
                if (uvalpha < 2048) {
                    for (0..w) |i| {
                        const Y: i32 = @as(i32, b0[i]) * 4;
                        const U: i32 = (@as(i32, u0[i]) - (128 << 7)) * 4;
                        const V: i32 = (@as(i32, v0[i]) - (128 << 7)) * 4;
                        var A: i32 = 255;
                        if (hasA) {
                            A = (@as(i32, p.a.?[0][i]) + 64) >> 7;
                            if (A & 0x100 != 0) A = std.math.clamp(A, 0, 255);
                        }
                        putFull(F, d, i, Y, U, V, A, t);
                    }
                } else {
                    const u1 = p.u[1];
                    const v1 = p.v[1];
                    for (0..w) |i| {
                        const Y: i32 = @as(i32, b0[i]) * 4;
                        const U: i32 = (@as(i32, u0[i]) + u1[i] - (128 << 8)) * 2;
                        const V: i32 = (@as(i32, v0[i]) + v1[i] - (128 << 8)) * 2;
                        var A: i32 = 255;
                        if (hasA) {
                            A = (@as(i32, p.a.?[0][i]) + 64) >> 7;
                            if (A & 0x100 != 0) A = std.math.clamp(A, 0, 255);
                        }
                        putFull(F, d, i, Y, U, V, A, t);
                    }
                }
            },
            2 => {
                const ya1 = 4096 - yalpha;
                const uva1 = 4096 - uvalpha;
                for (0..w) |i| {
                    const Y: i32 = (@as(i32, p.l[0][i]) * ya1 + @as(i32, p.l[1][i]) * yalpha) >> 10;
                    const U: i32 = (@as(i32, p.u[0][i]) * uva1 + @as(i32, p.u[1][i]) * uvalpha - (128 << 19)) >> 10;
                    const V: i32 = (@as(i32, p.v[0][i]) * uva1 + @as(i32, p.v[1][i]) * uvalpha - (128 << 19)) >> 10;
                    var A: i32 = 255;
                    if (hasA) {
                        A = (@as(i32, p.a.?[0][i]) * ya1 + @as(i32, p.a.?[1][i]) * yalpha + (1 << 18)) >> 19;
                        if (A & 0x100 != 0) A = std.math.clamp(A, 0, 255);
                    }
                    putFull(F, d, i, Y, U, V, A, t);
                }
            },
            else => {
                for (0..w) |i| {
                    var Y: i32 = 1 << 9;
                    var U: i32 = (1 << 9) - (128 << 19);
                    var V: i32 = (1 << 9) - (128 << 19);
                    for (p.lf, 0..) |c, j| Y += @as(i32, p.l[j][i]) * c;
                    for (p.cf, 0..) |c, j| {
                        U += @as(i32, p.u[j][i]) * c;
                        V += @as(i32, p.v[j][i]) * c;
                    }
                    Y >>= 10;
                    U >>= 10;
                    V >>= 10;
                    var A: i32 = 255;
                    if (hasA) {
                        A = 1 << 18;
                        for (p.lf, 0..) |c, j| A += @as(i32, p.a.?[j][i]) * c;
                        A >>= 19;
                        if (A & 0x100 != 0) A = std.math.clamp(A, 0, 255);
                    }
                    putFull(F, d, i, Y, U, V, A, t);
                }
            },
        }
    } else {
        const n = (w + 1) >> 1;
        switch (mode) {
            1 => {
                const b0 = p.l[0];
                const u0 = p.u[0];
                const v0 = p.v[0];
                if (uvalpha < 2048) {
                    for (0..n) |i| {
                        const Y1 = (@as(i32, b0[2 * i]) + 64) >> 7;
                        const Y2 = (@as(i32, b0[2 * i + 1]) + 64) >> 7;
                        const U = (@as(i32, u0[i]) + 64) >> 7;
                        const V = (@as(i32, v0[i]) + 64) >> 7;
                        putHalf(F, d, i, Y1, Y2, U, V, t);
                    }
                } else {
                    const u1 = p.u[1];
                    const v1 = p.v[1];
                    for (0..n) |i| {
                        const Y1 = (@as(i32, b0[2 * i]) + 64) >> 7;
                        const Y2 = (@as(i32, b0[2 * i + 1]) + 64) >> 7;
                        const U = (@as(i32, u0[i]) + u1[i] + 128) >> 8;
                        const V = (@as(i32, v0[i]) + v1[i] + 128) >> 8;
                        putHalf(F, d, i, Y1, Y2, U, V, t);
                    }
                }
            },
            2 => {
                const ya1 = 4096 - yalpha;
                const uva1 = 4096 - uvalpha;
                for (0..n) |i| {
                    const Y1 = (@as(i32, p.l[0][2 * i]) * ya1 + @as(i32, p.l[1][2 * i]) * yalpha) >> 19;
                    const Y2 = (@as(i32, p.l[0][2 * i + 1]) * ya1 + @as(i32, p.l[1][2 * i + 1]) * yalpha) >> 19;
                    const U = (@as(i32, p.u[0][i]) * uva1 + @as(i32, p.u[1][i]) * uvalpha) >> 19;
                    const V = (@as(i32, p.v[0][i]) * uva1 + @as(i32, p.v[1][i]) * uvalpha) >> 19;
                    putHalf(F, d, i, Y1, Y2, U, V, t);
                }
            },
            else => {
                for (0..n) |i| {
                    var Y1: i32 = 1 << 18;
                    var Y2: i32 = 1 << 18;
                    var U: i32 = 1 << 18;
                    var V: i32 = 1 << 18;
                    for (p.lf, 0..) |c, j| {
                        Y1 += @as(i32, p.l[j][2 * i]) * c;
                        Y2 += @as(i32, p.l[j][2 * i + 1]) * c;
                    }
                    for (p.cf, 0..) |c, j| {
                        U += @as(i32, p.u[j][i]) * c;
                        V += @as(i32, p.v[j][i]) * c;
                    }
                    putHalf(F, d, i, Y1 >> 19, Y2 >> 19, U >> 19, V >> 19, t);
                }
            },
        }
    }
}

// ── unscaled converters ────────────────────────────────────────────────────

pub fn yuv2rgbRow(f: i32, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, d: [*]u8, w: usize, t: *const Tables) void {
    switch (f) {
        main.RGB24 => yuv2rgbRowT(main.RGB24, py, pu, pv, d, w, t),
        main.BGR24 => yuv2rgbRowT(main.BGR24, py, pu, pv, d, w, t),
        main.RGBA => yuv2rgbRowT(main.RGBA, py, pu, pv, d, w, t),
        else => yuv2rgbRowT(main.BGRA, py, pu, pv, d, w, t),
    }
}

fn yuv2rgbRowT(comptime F: i32, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, d: [*]u8, w: usize, t: *const Tables) void {
    const n = w >> 1;
    for (0..n) |i| {
        putHalf(F, d, i, py[2 * i], py[2 * i + 1], pu[i], pv[i], t);
    }
    if (w & 1 != 0) {
        const i = n;
        const ui = tabIdx(pu[i]);
        const vi = tabIdx(pv[i]);
        const Y: i32 = py[2 * i];
        put(F, d, 2 * i, t.ytab[@intCast(Y + t.rV[vi])], t.ytab[@intCast(Y + t.gU[ui] + t.gV[vi])], t.ytab[@intCast(Y + t.bU[ui])], 255);
    }
}

pub fn interleave(a: [*]const u8, b: [*]const u8, d: [*]u8, w: usize) void {
    for (0..w) |i| {
        d[2 * i] = a[i];
        d[2 * i + 1] = b[i];
    }
}

pub fn deinterleave(s: [*]const u8, a: [*]u8, b: [*]u8, w: usize) void {
    for (0..w) |i| {
        a[i] = s[2 * i];
        b[i] = s[2 * i + 1];
    }
}

pub fn bgr24ToYv12Rows(s1: [*]const u8, s2: [*]const u8, y1: [*]u8, y2: [*]u8, ud: [*]u8, vd: [*]u8, w: usize, t: *const Tables) void {
    const ry = t.rgb2yuv[RY];
    const gy = t.rgb2yuv[GY];
    const by = t.rgb2yuv[BY];
    const ru = t.rgb2yuv[RU];
    const gu = t.rgb2yuv[GU];
    const bu = t.rgb2yuv[BU];
    const rv = t.rgb2yuv[RV];
    const gv = t.rgb2yuv[GV];
    const bv = t.rgb2yuv[BV];
    for (0..w >> 1) |i| {
        const b11: i32 = s1[6 * i + 0];
        const g11: i32 = s1[6 * i + 1];
        const r11: i32 = s1[6 * i + 2];
        const b12: i32 = s1[6 * i + 3];
        const g12: i32 = s1[6 * i + 4];
        const r12: i32 = s1[6 * i + 5];
        const b21: i32 = s2[6 * i + 0];
        const g21: i32 = s2[6 * i + 1];
        const r21: i32 = s2[6 * i + 2];
        const b22: i32 = s2[6 * i + 3];
        const g22: i32 = s2[6 * i + 4];
        const r22: i32 = s2[6 * i + 5];
        y1[2 * i] = @truncate(@as(u32, @intCast(((ry * r11 + gy * g11 + by * b11) >> 15) + 16)));
        y1[2 * i + 1] = @truncate(@as(u32, @intCast(((ry * r12 + gy * g12 + by * b12) >> 15) + 16)));
        y2[2 * i] = @truncate(@as(u32, @intCast(((ry * r21 + gy * g21 + by * b21) >> 15) + 16)));
        y2[2 * i + 1] = @truncate(@as(u32, @intCast(((ry * r22 + gy * g22 + by * b22) >> 15) + 16)));
        const bx = (b11 + b12 + b21 + b22) >> 2;
        const gx = (g11 + g12 + g21 + g22) >> 2;
        const rx = (r11 + r12 + r21 + r22) >> 2;
        ud[i] = @truncate(@as(u32, @bitCast(((ru * rx + gu * gx + bu * bx) >> 15) + 128)));
        vd[i] = @truncate(@as(u32, @bitCast(((rv * rx + gv * gx + bv * bx) >> 15) + 128)));
    }
}

pub fn rgb2rgbRow(sf: i32, df: i32, s: [*]const u8, d: [*]u8, w: usize) void {
    const sb = bpp(sf);
    const db = bpp(df);
    const sr = rOff(sf);
    const dr = rOff(df);
    for (0..w) |i| {
        const r = s[i * sb + sr];
        const g = s[i * sb + 1];
        const b = s[i * sb + 2 - sr];
        d[i * db + dr] = r;
        d[i * db + 1] = g;
        d[i * db + 2 - dr] = b;
        if (db == 4) d[i * db + 3] = if (sb == 4) s[i * sb + 3] else 255;
    }
}

