// ── vectorized input / scaler / output kernels ─────────────────────────────

inline fn chans(comptime F: i32, p: VI) [3]VI {
    const lo = p & sp(0xFF);
    const g = (p >> shv(8)) & sp(0xFF);
    const hi = (p >> shv(16)) & sp(0xFF);
    return if (F == main.RGB24 or F == main.RGBA) .{ lo, g, hi } else .{ hi, g, lo };
}

inline fn loadPix(comptime F: i32, s: [*]const u8) VI {
    return if (comptime bpp(F) == 4) load4p(s) else load3p(s);
}

inline fn storeI16(d: [*]i16, v: VI) void {
    const x: VI16 = @intCast(v);
    d[0..N].* = x;
}

inline fn storeU8(d: [*]u8, v: VI) void {
    const x: @Vector(N, u8) = @intCast(v);
    d[0..N].* = x;
}

// number of leading pixels for which reading `rd` bytes at pixel*bp stays inside the row
inline fn safeBlocks(w: usize, bp: usize, step: usize, rd: usize) usize {
    if (w * bp < rd) return 0;
    const lastStart = (w * bp - rd) / bp; // max start pixel
    return (lastStart / step + 1) * step;
}

pub fn rgbToYv(f: i32, src: [*]const u8, dst: [*]i16, w: usize, t: *const Tables, mul2: bool) void {
    switch (f) {
        main.RGB24 => rgbToYvT(main.RGB24, src, dst, w, t, mul2),
        main.BGR24 => rgbToYvT(main.BGR24, src, dst, w, t, mul2),
        main.RGBA => rgbToYvT(main.RGBA, src, dst, w, t, mul2),
        else => rgbToYvT(main.BGRA, src, dst, w, t, mul2),
    }
}

fn rgbToYvT(comptime F: i32, src: [*]const u8, dst: [*]i16, w: usize, t: *const Tables, mul2: bool) void {
    const B = comptime bpp(F);
    const R = comptime rOff(F);
    const ry = t.rgb2yuv[RY];
    const gy = t.rgb2yuv[GY];
    const by = t.rgb2yuv[BY];
    const nb = @min(safeBlocks(w, B, N, 64), w / N * N);
    var x: usize = 0;
    const m: i32 = if (mul2) 2 else 1;
    while (x < nb) : (x += N) {
        const c = chans(F, loadPix(F, src + x * B));
        const y = (sp(ry) * c[0] + sp(gy) * c[1] + sp(by) * c[2] + sp((32 << 14) + (1 << 8))) >> shv(9);
        storeI16(dst + x, y * sp(m));
    }
    for (x..w) |i| {
        const r: i32 = src[i * B + R];
        const g: i32 = src[i * B + 1];
        const b: i32 = src[i * B + 2 - R];
        dst[i] = @intCast(((ry * r + gy * g + by * b + (32 << 14) + (1 << 8)) >> 9) * m);
    }
}

pub fn rgbToUVv(f: i32, half: bool, src: [*]const u8, du: [*]i16, dv: [*]i16, w: usize, t: *const Tables, mul2: bool) void {
    switch (f) {
        main.RGB24 => rgbToUVvT(main.RGB24, half, src, du, dv, w, t, mul2),
        main.BGR24 => rgbToUVvT(main.BGR24, half, src, du, dv, w, t, mul2),
        main.RGBA => rgbToUVvT(main.RGBA, half, src, du, dv, w, t, mul2),
        else => rgbToUVvT(main.BGRA, half, src, du, dv, w, t, mul2),
    }
}

const mEven = blk: {
    var m: [16]i32 = undefined;
    for (0..8) |i| {
        m[i] = @intCast(2 * i);
        m[8 + i] = ~@as(i32, @intCast(2 * i));
    }
    break :blk m;
};
const mOdd = blk: {
    var m: [16]i32 = undefined;
    for (0..8) |i| {
        m[i] = @intCast(2 * i + 1);
        m[8 + i] = ~@as(i32, @intCast(2 * i + 1));
    }
    break :blk m;
};

fn rgbToUVvT(comptime F: i32, half: bool, src: [*]const u8, du: [*]i16, dv: [*]i16, w: usize, t: *const Tables, mul2: bool) void {
    const B = comptime bpp(F);
    const ru = t.rgb2yuv[RU];
    const gu = t.rgb2yuv[GU];
    const bu = t.rgb2yuv[BU];
    const rv = t.rgb2yuv[RV];
    const gv = t.rgb2yuv[GV];
    const bv = t.rgb2yuv[BV];
    const m: i32 = if (mul2) 2 else 1;
    var x: usize = 0;
    if (half) {
        // w = chroma width; source pixels 2w
        const nb = @min(if (safeBlocks(2 * w, B, 2 * N, 64 + N * B) > 0) safeBlocks(2 * w, B, 2 * N, 64 + N * B) / 2 else 0, w / N * N);
        while (x < nb) : (x += N) {
            const c0 = chans(F, loadPix(F, src + 2 * x * B));
            const c1 = chans(F, loadPix(F, src + (2 * x + N) * B));
            var s: [3]VI = undefined;
            inline for (0..3) |ch| {
                s[ch] = @shuffle(i32, c0[ch], c1[ch], mEven) + @shuffle(i32, c0[ch], c1[ch], mOdd);
            }
            const u = (sp(ru) * s[0] + sp(gu) * s[1] + sp(bu) * s[2] + sp((256 << 15) + (1 << 9))) >> shv(10);
            const v = (sp(rv) * s[0] + sp(gv) * s[1] + sp(bv) * s[2] + sp((256 << 15) + (1 << 9))) >> shv(10);
            storeI16(du + x, u * sp(m));
            storeI16(dv + x, v * sp(m));
        }
        if (x < w) {
            rgbToUVHalf(F, src + 2 * x * B, du + x, dv + x, w - x, t);
            if (mul2) for (x..w) |i| {
                du[i] *%= 2;
                dv[i] *%= 2;
            };
        }
    } else {
        const nb = @min(safeBlocks(w, B, N, 64), w / N * N);
        while (x < nb) : (x += N) {
            const c = chans(F, loadPix(F, src + x * B));
            const u = (sp(ru) * c[0] + sp(gu) * c[1] + sp(bu) * c[2] + sp((256 << 14) + (1 << 8))) >> shv(9);
            const v = (sp(rv) * c[0] + sp(gv) * c[1] + sp(bv) * c[2] + sp((256 << 14) + (1 << 8))) >> shv(9);
            storeI16(du + x, u * sp(m));
            storeI16(dv + x, v * sp(m));
        }
        if (x < w) {
            rgbToUV(F, src + x * B, du + x, dv + x, w - x, t);
            if (mul2) for (x..w) |i| {
                du[i] *%= 2;
                dv[i] *%= 2;
            };
        }
    }
}

fn hscaleT(comptime T: type, comptime FS: usize, comptime SH: u5, src: [*]const T, dst: [*]i16, f: *const Filter) void {
    const pos = f.pos;
    const coef = f.coef;
    for (0..f.n) |i| {
        const p: usize = @intCast(pos[i]);
        var val: i32 = 0;
        inline for (0..FS) |j| {
            const sv: i32 = if (T == u8) src[p + j] else @as(u16, @bitCast(src[p + j]));
            val += sv * coef[i * FS + j];
        }
        dst[i] = @intCast(@min(val >> SH, 32767));
    }
}

pub fn hscale8v(src: [*]const u8, dst: [*]i16, f: *const Filter) void {
    switch (f.size) {
        1 => hscaleT(u8, 1, 7, src, dst, f),
        2 => hscaleT(u8, 2, 7, src, dst, f),
        3 => hscaleT(u8, 3, 7, src, dst, f),
        4 => hscaleT(u8, 4, 7, src, dst, f),
        5 => hscaleT(u8, 5, 7, src, dst, f),
        6 => hscaleT(u8, 6, 7, src, dst, f),
        7 => hscaleT(u8, 7, 7, src, dst, f),
        8 => hscaleT(u8, 8, 7, src, dst, f),
        else => hscale8(src, dst, f),
    }
}

pub fn hscale16v(src: [*]const i16, dst: [*]i16, f: *const Filter) void {
    switch (f.size) {
        1 => hscaleT(i16, 1, 13, src, dst, f),
        2 => hscaleT(i16, 2, 13, src, dst, f),
        3 => hscaleT(i16, 3, 13, src, dst, f),
        4 => hscaleT(i16, 4, 13, src, dst, f),
        5 => hscaleT(i16, 5, 13, src, dst, f),
        6 => hscaleT(i16, 6, 13, src, dst, f),
        7 => hscaleT(i16, 7, 13, src, dst, f),
        8 => hscaleT(i16, 8, 13, src, dst, f),
        else => hscale16(src, dst, f),
    }
}

pub fn planeOutV(f: []const i16, rows: []const [*]const i16, dst: [*]u8, w: usize) void {
    const nb = w / N * N;
    var x: usize = 0;
    if (f.len == 1) {
        const s = rows[0];
        while (x < nb) : (x += N) storeU8(dst + x, clamp255((ld16(s + x) + sp(64)) >> shv(7)));
    } else {
        while (x < nb) : (x += N) {
            var val = sp(64 << 12);
            for (f, 0..) |c, j| val += ld16(rows[j] + x) * sp(c);
            storeU8(dst + x, clamp255(val >> shv(19)));
        }
    }
    if (x < w) {
        var tmp: [256][*]const i16 = undefined;
        for (rows, 0..) |r, j| tmp[j] = r + x;
        planeOut(f, tmp[0..rows.len], dst + x, w - x);
    }
}

const mNV = blk: {
    var m: [64]i32 = undefined;
    for (0..64) |j| m[j] = 63;
    for (0..16) |i| {
        m[2 * i] = @intCast(4 * i);
        m[2 * i + 1] = @intCast(4 * i + 1);
    }
    break :blk m;
};

pub fn nvOutV(f: []const i16, ur: []const [*]const i16, vr: []const [*]const i16, dst: [*]u8, w: usize) void {
    const nb = w / N * N;
    var x: usize = 0;
    while (x < nb) : (x += N) {
        var u = sp(64 << 12);
        var v = sp(64 << 12);
        for (f, 0..) |c, j| {
            u += ld16(ur[j] + x) * sp(c);
            v += ld16(vr[j] + x) * sp(c);
        }
        const p = clamp255(u >> shv(19)) | (clamp255(v >> shv(19)) << shv(8));
        const b: V64 = @bitCast(p);
        const o = @shuffle(u8, b, undefined, mNV);
        const arr: [64]u8 = o;
        dst[2 * x ..][0..32].* = arr[0..32].*;
    }
    if (x < w) {
        var tu: [256][*]const i16 = undefined;
        var tv: [256][*]const i16 = undefined;
        for (0..f.len) |j| {
            tu[j] = ur[j] + x;
            tv[j] = vr[j] + x;
        }
        nvOut(f, tu[0..f.len], tv[0..f.len], dst + 2 * x, w - x);
    }
}

inline fn swapRB(p: VI) VI {
    return (p & sp(@bitCast(@as(u32, 0xFF00FF00)))) | ((p & sp(0xFF)) << shv(16)) | ((p >> shv(16)) & sp(0xFF));
}

pub fn rgb2rgbRowV(sf: i32, df: i32, s: [*]const u8, d: [*]u8, w: usize) void {
    const sb = bpp(sf);
    const db = bpp(df);
    const swap = rOff(sf) != rOff(df);
    const nb = @min(safeBlocks(w, sb, N, 64), w / N * N);
    var x: usize = 0;
    while (x < nb) : (x += N) {
        var p = if (sb == 4) load4p(s + x * sb) else load3p(s + x * sb);
        if (swap) p = swapRB(p);
        if (db == 4) {
            if (sb == 3) p = p | sp(@bitCast(@as(u32, 0xFF000000)));
            store4p(d + x * db, p);
        } else {
            store3p(d + x * db, p);
        }
    }
    if (x < w) rgb2rgbRow(sf, df, s + x * sb, d + x * db, w - x);
}
