// ── periodic (polyphase) horizontal scaler ─────────────────────────────────
// When P consecutive outputs advance the source position by exactly Q, the
// taps of each phase are a strided sequence, which loads as vectors.

pub const HPlan = struct {
    P: usize,
    Q: usize,
    FS: usize,
    base: isize,
    off: [4]isize,
    gLo: usize,
    gEnd: usize,
    ng: usize,
    coefT: []i32,
};

fn readLen(Q: usize) usize {
    return switch (Q) {
        1 => 16,
        2 => 32,
        else => 64,
    };
}

pub fn makePlan(alloc: std.mem.Allocator, f: *const Filter, srcLen: usize, xInc: i64) ?HPlan {
    const n = f.n;
    const FS = f.size;
    if (FS > 16 or n < 64) return null;
    var P: usize = 1;
    while (P <= 4) : (P += 1) {
        const num: i64 = @as(i64, @intCast(P)) * xInc;
        const Qi: i64 = @divTrunc(num + 32768, 65536);
        if (Qi < 1 or Qi > 4) continue;
        if (@abs(num - Qi * 65536) > 64) continue;
        const Q: usize = @intCast(Qi);
        const ng = n / P;
        const g0 = ng / 2;
        const base: isize = @as(isize, f.pos[P * g0]) - @as(isize, @intCast(Q * g0));
        var off: [4]isize = .{ 0, 0, 0, 0 };
        for (0..P) |ph| off[ph] = @as(isize, f.pos[P * g0 + ph]) - @as(isize, f.pos[P * g0]);
        const reg = struct {
            fn ok(ff: *const Filter, PP: usize, QQ: usize, bb: isize, oo: [4]isize, g: usize) bool {
                for (0..PP) |ph| {
                    const want = bb + @as(isize, @intCast(QQ * g)) + oo[ph];
                    if (@as(isize, ff.pos[PP * g + ph]) != want) return false;
                }
                return true;
            }
        };
        if (!reg.ok(f, P, Q, base, off, g0)) continue;
        var gLo = g0;
        while (gLo > 0 and reg.ok(f, P, Q, base, off, gLo - 1)) gLo -= 1;
        var gHi = g0 + 1;
        while (gHi < ng and reg.ok(f, P, Q, base, off, gHi)) gHi += 1;
        // read bound: base + maxoff + FS-1 + Q*g + READ <= srcLen for every group in a block
        var maxoff: isize = 0;
        for (0..P) |ph| maxoff = @max(maxoff, off[ph]);
        const lim: isize = @as(isize, @intCast(srcLen)) - base - maxoff - @as(isize, @intCast(FS - 1)) - @as(isize, @intCast(readLen(Q)));
        if (lim < 0) continue;
        const gMaxRead: usize = @intCast(@divTrunc(lim, @as(isize, @intCast(Q)))); // last group start allowed
        // a block [g, g+16) needs g + 15 <= gMaxRead
        var gEnd = gHi;
        if (gMaxRead + 1 < gEnd) gEnd = gMaxRead + 1;
        if (gEnd < gLo + 32) continue;
        const coefT = alloc.alloc(i32, P * FS * ng + 16) catch return null;
        for (0..P) |ph| {
            for (0..FS) |j| {
                for (0..ng) |g| coefT[(ph * FS + j) * ng + g] = f.coef[(P * g + ph) * FS + j];
            }
        }
        return .{ .P = P, .Q = Q, .FS = FS, .base = base, .off = off, .gLo = gLo, .gEnd = gEnd, .ng = ng, .coefT = coefT };
    }
    return null;
}

inline fn loadQ(comptime T: type, comptime Q: usize, p: [*]const T) VI {
    if (T == u8) {
        switch (Q) {
            1 => return ldu8(p),
            2 => {
                const v: @Vector(16, u16) = @bitCast(p[0..32].*);
                return @intCast(v & @as(@Vector(16, u16), @splat(0xFF)));
            },
            3 => return load3p(p) & sp(0xFF),
            else => return load4p(p) & sp(0xFF),
        }
    } else {
        switch (Q) {
            1 => return ld16(p),
            2 => {
                const v: @Vector(16, u32) = @bitCast(p[0..32].*);
                return @bitCast(v & @as(@Vector(16, u32), @splat(0xFFFF)));
            },
            3 => {
                const v: @Vector(64, i16) = p[0..64].*;
                const o = @shuffle(i16, v, undefined, mStride3);
                const arr: [4]@Vector(16, i16) = @bitCast(o);
                const r: @Vector(16, u16) = @bitCast(arr[0]);
                return @intCast(r);
            },
            else => {
                const v: @Vector(16, u64) = @bitCast(p[0..64].*);
                return @intCast(v & @as(@Vector(16, u64), @splat(0xFFFF)));
            },
        }
    }
}

const mStride3 = blk: {
    var m: [64]i32 = undefined;
    for (0..64) |j| m[j] = 63;
    for (0..16) |kk| m[kk] = @intCast(3 * kk);
    break :blk m;
};

fn mkInterleave(comptime P: usize, comptime part: usize, comptime stage: usize) [16]i32 {
    // stage 0: combine phases 0/1 ; stage 1: combine phases 2/3 ; stage 2: merge
    var m: [16]i32 = undefined;
    for (0..16) |l| {
        const L = 16 * part + l;
        const ph = L % P;
        const grp: i32 = @intCast(L / P);
        m[l] = switch (stage) {
            0 => if (ph == 0) grp else if (ph == 1) ~grp else 0,
            1 => if (ph == 2) grp else if (ph == 3) ~grp else 0,
            else => if (P == 3) (if (ph == 2) ~grp else @as(i32, @intCast(l))) else (if (ph < 2) @as(i32, @intCast(l)) else ~@as(i32, @intCast(l))),
        };
    }
    return m;
}

inline fn storeP(comptime P: usize, dst: [*]i16, r: [P]VI) void {
    if (P == 1) {
        storeI16(dst, r[0]);
    } else if (P == 2) {
        inline for (0..2) |part| {
            storeI16(dst + 16 * part, @shuffle(i32, r[0], r[1], comptime mkInterleave(2, part, 0)));
        }
    } else {
        inline for (0..P) |part| {
            const t = @shuffle(i32, r[0], r[1], comptime mkInterleave(P, part, 0));
            const o = if (P == 3)
                @shuffle(i32, t, r[2], comptime mkInterleave(P, part, 2))
            else
                @shuffle(i32, t, @shuffle(i32, r[2], r[3], comptime mkInterleave(P, part, 1)), comptime mkInterleave(P, part, 2));
            storeI16(dst + 16 * part, o);
        }
    }
}

fn hscaleRange(comptime T: type, comptime SH: u5, src: [*]const T, dst: [*]i16, f: *const Filter, from: usize, to: usize) void {
    const fs = f.size;
    for (from..to) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| {
