                acc += loadQ(T, Q, src + s0 + j) * c;
            }
            res[ph] = @min(acc >> shv(SH), sp(32767));
        }
        storeP(P, dst + P * g, res);
    }
    hscaleRange(T, SH, src, dst, f, P * g, f.n);
}

pub fn hscalePlan(comptime T: type, src: [*]const T, dst: [*]i16, f: *const Filter, pl: *const HPlan) void {
    const SH: u5 = if (T == u8) 7 else 13;
    switch (pl.P) {
        inline 1...4 => |P| switch (pl.Q) {
            inline 1...4 => |Q| hscalePlanT(T, P, Q, SH, src, dst, f, pl),
            else => unreachable,
        },
        else => unreachable,
    }
}
