inline fn storeP(comptime P: usize, dst: [*]i16, r: [P]VI) void {
    if (P == 1) {
        storeI16(dst, r[0]);
    } else if (P == 2) {
        inline for (0..2) |part| {
            storeI16(dst + 16 * part, @shuffle(i32, r[0], r[1], comptime mkInterleave(2, part, 0)));
        }
    } else {
