fn hscaleRange(comptime T: type, comptime SH: u5, src: [*]const T, dst: [*]i16, f: *const Filter, from: usize, to: usize) void {
    const fs = f.size;
    for (from..to) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| {
            const sv: i32 = if (T == u8) src[p + j] else @as(u16, @bitCast(src[p + j]));
            val += sv * f.coef[i * fs + j];
        }
        dst[i] = @intCast(@min(val >> SH, 32767));
    }
}

fn hscalePlanT(comptime T: type, comptime P: usize, comptime Q: usize, comptime SH: u5, src: [*]const T, dst: [*]i16, f: *const Filter, pl: *const HPlan) void {
    var g = pl.gLo;
    hscaleRange(T, SH, src, dst, f, 0, P * g);
    const FS = pl.FS;
    const ng = pl.ng;
