pub fn rgbPointY(f: i32, src: [*]const u8, pos: []const i32, dst: [*]i16, n: usize, rowBytes: usize, t: *const Tables) void {
    switch (f) {
        inline main.RGB24...main.BGRA => |F| rgbPointYT(F, src, pos, dst, n, rowBytes, t),
        else => unreachable,
    }
}

fn rgbPointYT(comptime F: i32, src: [*]const u8, pos: []const i32, dst: [*]i16, n: usize, rowBytes: usize, t: *const Tables) void {
    const B = comptime bpp(F);
    const R = comptime rOff(F);
    const ry = t.rgb2yuv[RY];
    const gy = t.rgb2yuv[GY];
    const by = t.rgb2yuv[BY];
